require 'net/smtp'
require 'json'
require 'logger'

module SearchIndexer
  class CircuitBreaker
    STATES = [:closed, :open, :half_open].freeze

    attr_reader :state, :failure_count, :last_failure_time

    def initialize(threshold: 5, timeout: 30)
      @state = :closed
      @failure_count = 0
      @threshold = threshold
      @timeout = timeout
      @last_failure_time = nil
      @logger = Logger.new(STDOUT)
    end

    def call(&block)
      case @state
      when :closed
        begin
          result = block.call
          reset!
          result
        rescue => e
          record_failure(e)
          raise
        end
      when :open
        if Time.now - @last_failure_time >= @timeout
          @state = :half_open
          call(&block)
        else
          raise CircuitOpenError, "Circuit is open until #{@last_failure_time + @timeout}"
        end
      when :half_open
        begin
          result = block.call
          reset!
          result
        rescue => e
          @state = :open
          @last_failure_time = Time.now
          raise
        end
      end
    end

    private

    def record_failure(error)
      @failure_count += 1
      @last_failure_time = Time.now
      if @failure_count >= @threshold
        @state = :open
        @logger.warn("Circuit opened after #{@failure_count} failures")
      end
    end

    def reset!
      @failure_count = 0
      @state = :closed
    end
  end

  class CircuitOpenError < StandardError; end

  class NotificationMailer
    def initialize(smtp_host: 'localhost', smtp_port: 25)
      @smtp_host = smtp_host
      @smtp_port = smtp_port
    end

    def send_alert(recipient:, subject:, body:, metadata: {})
      headers = build_headers(recipient, subject, metadata)
      message = compose_message(headers, body)

      Net::SMTP.start(@smtp_host, @smtp_port) do |smtp|
        smtp.send_message(message, 'indexer@internal.corp', recipient)
      end
    end

    private

    def build_headers(recipient, subject, metadata)
      headers = [
        ["From", "Search Indexer <indexer@internal.corp>"],
        ["To", recipient],
        ["Subject", subject],
        ["MIME-Version", "1.0"],
        ["Content-Type", "text/plain; charset=UTF-8"],
        ["X-Mailer", "SearchIndexer/2.1"]
      ]

      metadata.each do |key, value|
        safe_key = sanitize_header_name(key.to_s)
        safe_value = encode_header_value(value.to_s)
        headers << ["X-Index-#{safe_key}", safe_value]
      end

      headers
    end

    def sanitize_header_name(name)
      name.gsub(/[^a-zA-Z0-9\-]/, '-')
    end

    def encode_header_value(value)
      # RFC 2047 Q-encoding for non-ASCII, pass through ASCII
      if value.ascii_only?
        value
      else
        "=?UTF-8?B?#{[value].pack('m0')}?="
      end
    end

    def compose_message(headers, body)
      header_block = headers.map { |k, v| "#{k}: #{v}" }.join("\r\n")
      "#{header_block}\r\n\r\n#{body}"
    end
  end

  class IndexService
    def initialize(config = {})
      @circuit = CircuitBreaker.new(
        threshold: config.fetch(:circuit_threshold, 5),
        timeout: config.fetch(:circuit_timeout, 30)
      )
      @mailer = NotificationMailer.new(
        smtp_host: config.fetch(:smtp_host, 'localhost'),
        smtp_port: config.fetch(:smtp_port, 25)
      )
      @admin_email = config.fetch(:admin_email, 'admin@internal.corp')
      @logger = Logger.new(STDOUT)
    end

    def index_document(document)
      @circuit.call do
        result = perform_indexing(document)
        @logger.info("Indexed document: #{document[:id]}")
        result
      end
    rescue CircuitOpenError => e
      notify_circuit_open(document)
      raise
    rescue => e
      notify_indexing_failure(document, e)
      raise
    end

    private

    def perform_indexing(document)
      # Simulate indexing to search backend
      { status: 'indexed', id: document[:id], timestamp: Time.now.iso8601 }
    end

    def notify_circuit_open(document)
      @mailer.send_alert(
        recipient: @admin_email,
        subject: "[ALERT] Search indexer circuit open",
        body: "Circuit breaker opened. Last document: #{document[:id]}",
        metadata: {
          document_id: document[:id],
          document_source: document[:source],
          circuit_state: "open"
        }
      )
    end

    def notify_indexing_failure(document, error)
      @mailer.send_alert(
        recipient: @admin_email,
        subject: "[ERROR] Indexing failed for #{document[:id]}",
        body: "Error: #{error.message}\nDocument: #{document[:id]}",
        metadata: {
          document_id: document[:id],
          error_class: error.class.name,
          error_detail: error.message
        }
      )
    end
  end
end
